"""matplotlib._type1font — Type 1 PostScript font reader stub.

Used by the real PostScript / PDF / PGF backends; the plotly backend
neither parses nor embeds Type 1 fonts, so the class is import-only.
"""


class Type1Font:
    def __init__(self, input=None):
        self.parts = (b'', b'', b'')

    @property
    def prop(self): return {}

    def transform(self, effects): return self
    def with_encoding(self, encoding): return self
    def to_unicode(self, glyph): return ''


def find_encoding(*args, **kwargs): return None
